require __DIR__.'/includes/config.php'; lab_sensitive_page('contrataciones.php','Contrataciones'); $q=trim($_GET['q']??''); $page=max(1,(int)($_GET['page']??1)); $per=20; $offset=($page-1)*$per; $params=[]; $where=''; if($q!==''){ $where=' WHERE c.numero LIKE ? OR c.objeto LIKE ? OR p.nombre LIKE ? '; $params=['%'.$q.'%','%'.$q.'%','%'.$q.'%']; }
$ct=db()->prepare('SELECT COUNT(*) FROM contratos c JOIN proveedores p ON p.id=c.proveedor_id'.$where); $ct->execute($params); $total=(int)$ct->fetchColumn(); $st=db()->prepare('SELECT c.*,p.nombre proveedor FROM contratos c JOIN proveedores p ON p.id=c.proveedor_id'.$where.' ORDER BY c.fecha_inicio DESC,c.id DESC LIMIT '.$per.' OFFSET '.$offset); $st->execute($params); $rows=$st->fetchAll(); $pages=max(1,(int)ceil($total/$per));
$pageTitle='Contrataciones'; include __DIR__.'/includes/header.php'; ?>
<section class="section"><div class="wrap"><div class="eyebrow">Transparencia contractual</div><h1>Contrataciones vigentes y concluidas</h1><p class="section-intro">Consulta número de contrato, proveedor, objeto, modalidad, monto, vigencia y origen del recurso.</p><div class="search-panel"><div><b><?= number_format($total) ?></b><span>contratos disponibles para consulta</span></div><form class="search-form"><input name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Contrato, proveedor u objeto"><button class="btn">Buscar</button><a class="btn btn-light" href="/exportar.php?tipo=contratos">CSV</a></form></div><div class="table-wrap section-spacer"><table class="table contract-table"><thead><tr><th>Contrato</th><th>Proveedor / objeto</th><th>Modalidad</th><th>Monto</th><th>Origen</th><th>Vigencia</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= htmlspecialchars($r['numero']) ?></b><br><span class="tag"><?= htmlspecialchars($r['estado']) ?></span></td><td><b><?= htmlspecialchars($r['proveedor']) ?></b><small><?= htmlspecialchars($r['objeto']) ?></small></td><td><?= htmlspecialchars($r['modalidad']) ?></td><td>$<?= number_format((float)$r['monto'],2) ?></td><td><?= htmlspecialchars($r['origen_recurso']) ?></td><td><?= htmlspecialchars($r['fecha_inicio']) ?><br><?= htmlspecialchars($r['fecha_fin']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><?php for($i=1;$i<=$pages;$i++): if($i==1||$i==$pages||abs($i-$page)<=2): ?><a class="<?= $i===$page?'active':'' ?>" href="?q=<?= urlencode($q) ?>&page=<?= $i ?>"><?= $i ?></a><?php elseif($i==2 && $page>4 || $i==$pages-1 && $page<$pages-3): ?><span>…</span><?php endif; endfor; ?></div></div></section>
